/* ===========================================================
   Componentes utilitários
   =========================================================== */
@layer components {
  /* Container padrão */
  .container-lp {
    @apply mx-auto w-full max-w-container px-5 sm:px-6 lg:px-8;
  }

  /* Espaçamento vertical de seção */
  .section-py {
    @apply py-20 md:py-28 lg:py-32;
  }

  /* Card glass padrão — inspirado Luminna: gradient border com máscara */
  .glass-card {
    position: relative;
    background:
      radial-gradient(120% 80% at 0% 0%, rgba(14, 216, 246, 0.1), transparent 55%),
      radial-gradient(120% 80% at 100% 100%, rgba(124, 58, 237, 0.1), transparent 55%),
      linear-gradient(135deg, rgba(15, 90, 151, 0.88), rgba(17, 95, 160, 0.55));
    border: 1px solid var(--border-soft);
    border-radius: var(--radius-card);
    backdrop-filter: blur(22px) saturate(1.2);
    -webkit-backdrop-filter: blur(22px) saturate(1.2);
    box-shadow:
      0 24px 50px -22px rgba(13, 88, 149, 0.9),
      0 2px 10px -4px rgba(13, 88, 151, 0.5),
      inset 0 1px 0 rgba(255, 255, 255, 0.08),
      inset 0 -1px 0 rgba(0, 0, 0, 0.25);
    overflow: hidden;
    isolation: isolate;
  }
  .glass-card::before {
    content: '';
    position: absolute;
    inset: 0;
    border-radius: inherit;
    padding: 1px;
    background: linear-gradient(
      135deg,
      rgba(120, 201, 248, 0.55),
      rgba(124, 58, 237, 0.35) 45%,
      rgba(14, 216, 246, 0.12) 75%,
      transparent 100%
    );
    -webkit-mask:
      linear-gradient(#000 0 0) content-box,
      linear-gradient(#000 0 0);
    mask:
      linear-gradient(#000 0 0) content-box,
      linear-gradient(#000 0 0);
    -webkit-mask-composite: xor;
    mask-composite: exclude;
    pointer-events: none;
    opacity: 0.75;
    transition: opacity 0.35s ease;
  }
  .glass-card::after {
    content: '';
    position: absolute;
    top: -40%;
    left: -20%;
    width: 80%;
    height: 80%;
    background: radial-gradient(circle at center, rgba(14, 216, 246, 0.18), transparent 60%);
    filter: blur(30px);
    opacity: 0;
    transition:
      opacity 0.4s ease,
      transform 0.6s ease;
    pointer-events: none;
    z-index: -1;
  }

  /* Card com hover ativo */
  .glass-card-hover {
    @apply glass-card transition-all duration-300 ease-out;
    will-change: transform;
  }
  .glass-card-hover:hover {
    transform: translateY(-6px) scale(1.005);
    border-color: var(--border-active);
    box-shadow:
      0 34px 70px -22px rgba(0, 121, 203, 0.55),
      0 0 0 1px rgba(120, 201, 248, 0.3) inset,
      inset 0 1px 0 rgba(255, 255, 255, 0.14);
  }
  .glass-card-hover:hover::before {
    opacity: 1;
  }
  .glass-card-hover:hover::after {
    opacity: 1;
    transform: translate(10%, 10%);
  }

  /* Textos de destaque (sem gradiente) */
  .text-gradient {
    color: #a5f3fc;
  }
  .text-gradient-accent {
    color: #d6ecfb;
  }

  /* Botão primário */
  .btn-primary {
    @apply relative inline-flex items-center justify-center gap-2 rounded-full px-6 py-3 text-sm font-semibold text-white transition-all duration-300;
    background: linear-gradient(135deg, #0ed8f6 0%, #0099e6 40%, #0079cb 100%);
    box-shadow:
      0 14px 34px -10px rgba(0, 121, 203, 0.6),
      0 2px 6px -2px rgba(0, 60, 120, 0.35),
      inset 0 1px 0 rgba(255, 255, 255, 0.35),
      inset 0 -1px 0 rgba(13, 94, 161, 0.35);
    overflow: hidden;
    isolation: isolate;
  }
  .btn-primary::before {
    content: '';
    position: absolute;
    inset: 0;
    border-radius: inherit;
    background: linear-gradient(
      120deg,
      transparent 30%,
      rgba(255, 255, 255, 0.28) 50%,
      transparent 70%
    );
    transform: translateX(-120%);
    transition: transform 0.7s cubic-bezier(0.22, 1, 0.36, 1);
    pointer-events: none;
  }
  .btn-primary:hover {
    transform: translateY(-2px);
    box-shadow:
      0 20px 42px -8px rgba(0, 121, 203, 0.72),
      0 4px 12px -2px rgba(14, 216, 246, 0.35),
      inset 0 1px 0 rgba(255, 255, 255, 0.45);
  }
  .btn-primary:hover::before {
    transform: translateX(120%);
  }
  .btn-primary:active {
    transform: translateY(0);
  }

  /* Botão secundário / outline glass */
  .btn-ghost {
    @apply relative inline-flex items-center justify-center gap-2 rounded-full px-6 py-3 text-sm font-semibold text-ink transition-all duration-300;
    border: 1px solid var(--border-soft);
    background: linear-gradient(135deg, rgba(13, 98, 163, 0.55), rgba(0, 77, 138, 0.35));
    backdrop-filter: blur(14px) saturate(1.1);
    -webkit-backdrop-filter: blur(14px) saturate(1.1);
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.08);
  }
  .btn-ghost:hover {
    border-color: var(--border-active);
    background: linear-gradient(135deg, rgba(0, 77, 138, 0.85), rgba(0, 121, 203, 0.6));
    color: #ffffff;
    transform: translateY(-2px);
    box-shadow:
      0 12px 30px -12px rgba(0, 121, 203, 0.55),
      inset 0 1px 0 rgba(255, 255, 255, 0.16);
  }

  /* Pill / chip */
  .pill {
    @apply inline-flex items-center gap-1.5 rounded-full px-3 py-1 text-xs font-medium;
    background: rgba(13, 98, 163, 0.7);
    border: 1px solid var(--border-soft);
    color: #cbd5e1;
  }

  /* Pill de categoria com tom acentuado */
  .pill-accent {
    @apply pill;
    color: #d6ecfb;
    border-color: rgba(13, 95, 161, 0.4);
    background: rgba(13, 95, 161, 0.14);
  }

  /* Eyebrow (rótulo acima de título) */
  .eyebrow {
    @apply relative inline-flex items-center gap-2 text-xs font-semibold uppercase tracking-[0.22em];
    color: #7dd3fc;
  }
  .eyebrow::before {
    content: '';
    width: 6px;
    height: 6px;
    border-radius: 999px;
    background: #0ed8f6;
    box-shadow:
      0 0 0 3px rgba(14, 216, 246, 0.18),
      0 0 12px rgba(14, 216, 246, 0.55);
    animation: eyebrow-pulse 2.6s ease-in-out infinite;
  }
  @keyframes eyebrow-pulse {
    0%,
    100% {
      box-shadow:
        0 0 0 3px rgba(14, 216, 246, 0.18),
        0 0 8px rgba(14, 216, 246, 0.45);
    }
    50% {
      box-shadow:
        0 0 0 5px rgba(14, 216, 246, 0.1),
        0 0 18px rgba(14, 216, 246, 0.75);
    }
  }

  /* SIS-261 — MODIFICADOR: traço em vez do ponto pulsante.
     A issue pede «traço ciano + ESG», e o `.eyebrow` da casa nasce com um ponto
     de 6px. Isto é modificador e não rótulo novo de propósito: herda a tipografia
     inteira do `.eyebrow` (caps, `tracking-[0.22em]`, peso 600) e também o
     override de cor para fundo claro (`.section-light [class*='eyebrow']`, mais
     abaixo), que casa por substring e portanto já alcança este nome.

     A GEOMETRIA DO TRAÇO NÃO É INVENTADA: é a da `.titulo-risco`, o traço que a
     casa já usa sob os títulos — 2px de altura e o mesmo gradiente
     `#0079cb → #0ed8f6`, reduzido a 22px de largura porque aqui ele acompanha um
     rótulo de 12px, não um título.

     CIANO NO TRAÇO, NÃO NO TEXTO. Sobre fundo claro, `#0ed8f6` como cor de texto
     não passa AA (contra o claro da seção fica na casa de 1,5:1). O traço é
     GRAFISMO — não tem piso de contraste — então o ciano vive nele, e a palavra
     «ESG» fica no `#024e86` que o override de fundo claro já aplica. É a leitura
     do «traço ciano + ESG (caps, ciano)» da issue que não quebra acessibilidade.

     Sem `animation`: o ponto pulsa, o traço não. Um traço que pulsa vira
     chamariz, e movimento infinito sem pausa é o que a casa evita. */
  .eyebrow--traco::before {
    width: 22px;
    height: 2px;
    border-radius: 2px;
    background: linear-gradient(90deg, #0079cb, #0ed8f6 55%, #a5f0ff);
    box-shadow: none;
    animation: none;
  }

  /* Tag de seção — versão "chip" do eyebrow, com moldura e fundo.
     Usar quando o rótulo precisa de mais presença acima do título. */
  .tag-section {
    @apply relative inline-flex items-center gap-2.5 rounded-full border px-3.5 py-1.5 text-[11px] font-semibold uppercase tracking-[0.2em];
    color: #b8ddf6;
    border-color: rgba(255, 255, 255, 0.14);
    background: rgba(255, 255, 255, 0.04);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
  }
  .tag-section::before {
    content: '';
    width: 6px;
    height: 6px;
    border-radius: 999px;
    background: #0ed8f6;
    box-shadow:
      0 0 0 3px rgba(14, 216, 246, 0.18),
      0 0 12px rgba(14, 216, 246, 0.55);
    animation: eyebrow-pulse 2.6s ease-in-out infinite;
  }
  /* Sobre fundo claro a moldura inverte para azul da marca */
  .section-light .tag-section {
    color: #0060a8;
    border-color: rgba(0, 121, 203, 0.22);
    background: rgba(255, 255, 255, 0.72);
    box-shadow: 0 10px 30px -22px rgba(0, 121, 203, 0.7);
  }

  /* Title fluído — hierarquia de landing pesada */
  .title-display {
    font-size: clamp(2.25rem, 5.6vw, 4.75rem);
    line-height: 1.02;
    letter-spacing: -0.035em;
    font-weight: 700;
  }
  .title-section {
    font-size: clamp(1.75rem, 3.6vw, 3rem);
    line-height: 1.08;
    letter-spacing: -0.028em;
    font-weight: 700;
  }

  /* Divider sutil azul->violeta */
  .divider-accent {
    height: 1px;
    background: linear-gradient(
      90deg,
      transparent,
      rgba(14, 216, 246, 0.55),
      rgba(124, 58, 237, 0.45),
      transparent
    );
    border: 0;
  }
}

/* ===========================================================
   Alternância de fundo: escuro (padrão) ↔ claro (Luminna light)
   =========================================================== */

/* A seção seguinte "sobe" por cima do hero enquanto ele afunda */
#top {
  z-index: 0;
}
#top + * {
  position: relative;
  z-index: 1;
