  .os-palco[data-ativa] .bm-mapa g[data-cidade] > circle,
  .os-palco[data-ativa] .bm-mapa g[data-cidade] > .bm-gota {
    transform: none !important;
  }
  .os-palco[data-modo='scroll'] .bm-divisas-br {
    opacity: 1 !important;
  }
  .bm-pais-cabeca {
    display: none;
  }
