--- fim do bloco comentado pela SIS-153 --- */

.evento-descricao {
  margin-top: 1rem;
  max-width: 46ch;
  font-size: 1rem;
  line-height: 1.65;
  color: rgba(233, 244, 255, 0.88);
}

.evento-chip {
  border-width: 1px;
  border-style: solid;
  border-radius: 999px;
  padding: 0.45rem 0.9rem;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
