.hero-backdrop--carreira .hero-backdrop-veu {
  background:
    linear-gradient(
      96deg,
      rgb(4 27 61 / 0%) 0%,
      rgb(4 27 61 / 10%) 30%,
      rgb(4 27 61 / 26%) 62%,
      rgb(4 27 61 / 34%) 100%
    ),
    linear-gradient(
      180deg,
      rgb(3 17 38 / 64%) 0%,
      rgb(4 27 61 / 44%) 45%,
      rgb(4 27 61 / 62%) 72%,
      rgb(4 27 61 / 82%) 100%
    ),
    rgb(4 27 61 / 12%);
