       | --cta-ref-cartao-w: min(58vw, 1180px);
       | --cta-ref-arte-w: clamp(420px, 32vw, 640px);
       | --cta-ref-arte-margem: clamp(24px, 7vw, 130px);
       | --cta-ref-botao-w: clamp(250px, 18vw, 350px);
