    radial-gradient(70% 60% at 18% 8%, rgba(0, 121, 203, 0.14), transparent 62%),
    radial-gradient(55% 60% at 92% 88%, rgba(14, 216, 246, 0.1), transparent 62%),
    linear-gradient(160deg, #f2f9fe 0%, #e3f1fb 45%, #cfe7f7 100%);
